const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/budget_views/%7Bbudget_view_id%7D/project_status_snapshots',
  qs: {
    'filters[status_id]': 'SOME_STRING_VALUE',
    'filters[approval_status]': 'approved',
    'filters[financial_period_id][]': ['42', 'null'],
    comparison_budget_column_ids: ['12345', '6789'],
    sort: '-created_at',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/budget_views/%7Bbudget_view_id%7D/project_status_snapshots?filters%5Bstatus_id%5D=SOME_STRING_VALUE&filters%5Bapproval_status%5D=approved&filters%5Bfinancial_period_id%5D%5B%5D=42&filters%5Bfinancial_period_id%5D%5B%5D=null&comparison_budget_column_ids=12345&comparison_budget_column_ids=6789&sort=-created_at&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

